SELECT r.* FROM resume r LEFT JOIN user u ON r.user_id = u.user_id
AND u.name LIKE CONCAT('%', #{name}, '%')
AND u.major LIKE CONCAT('%', #{major}, '%')
AND EXISTS ( SELECT 1 FROM interview_preference ip LEFT JOIN department pd1 ON pd1.dept_id = ip.first_dept_id LEFT JOIN department pd2 ON pd2.dept_id = ip.second_dept_id WHERE ip.resume_id = r.resume_id
AND pd1.dept_name = #{expectedDepartment}
AND pd2.dept_name = #{expectedDepartment}
)
AND ( EXISTS ( SELECT 1 FROM interview_preference ip LEFT JOIN department pd1 ON pd1.dept_id = ip.first_dept_id LEFT JOIN department pd2 ON pd2.dept_id = ip.second_dept_id WHERE ip.resume_id = r.resume_id AND (pd1.dept_name = #{expectedDepartment} OR pd2.dept_name = #{expectedDepartment}) ) OR EXISTS ( SELECT 1 FROM resume_field_value rv JOIN resume_field_definition rf ON rv.field_id = rf.field_id WHERE rv.resume_id = r.resume_id AND rf.field_key = 'expected_departments' AND rv.field_value LIKE CONCAT('%', #{expectedDepartment}, '%') ) )
AND r.cycle_id = #{cycleId}
AND r.status IN
